target:
"SELECT $this WHERE {
            <urn:usf:ontology> usf:mandatoryFacets/rdf:rest*/rdf:first ?required .
            FILTER NOT EXISTS {
                $this usf:declaresFacet ?f . ?f usf:facetKind ?required .
            }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            FILTER NOT EXISTS { $this usf:observedInCensusRun ?run }
            $this ?p ?o .
            FILTER(isLiteral(?o))
            FILTER(REGEX(STR(?o),'linear[.]app|github[.]com|gitlab[.]com|refs/heads|commitSha|branchName|issueId|projectId|ADR-[0-9]|USF-[0-9]'))
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            FILTER NOT EXISTS { $this usf:observedInCensusRun ?run }
            FILTER(isIRI($this))
            FILTER(REGEX(STR($this),'linear[.]app|github[.]com|gitlab[.]com|refs/heads|commitSha|branchName|issueId|projectId|ADR-[0-9]|USF-[0-9]','i'))
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            FILTER(isIRI($this) && STRSTARTS(STR($this),'urn:usf:'))
            $this usf:canonicalName ?cn .
            BIND(REPLACE(STR($this),'^.*:','') AS ?loc)
            FILTER(?loc != STR(?cn))
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            FILTER(isIRI($this) && STRSTARTS(STR($this),'urn:usf:'))
            BIND(REPLACE(STR($this),'^.*:','') AS ?loc)
            FILTER(REGEX(?loc,'[-_]'))
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            $this usf:claimedRung ?c . ?c usf:rungOrder ?co .
            $this usf:observedRung ?o . ?o usf:rungOrder ?oo .
            FILTER(?co > ?oo)
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          { $this usf:applicabilityStatus <urn:usf:applicabilitystatus:applicable> .
            FILTER NOT EXISTS { $this usf:implementedBy ?implementation } }
          UNION
          { $this usf:applicabilityStatus <urn:usf:applicabilitystatus:notapplicable> .
            FILTER NOT EXISTS { $this usf:approvedByReview ?review } }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:approvalState <urn:usf:controlstatus:approved> .
          { FILTER NOT EXISTS { $this usf:soaApprovedByReview ?review } }
          UNION
          { $this usf:hasApplicabilityDecision/usf:applicabilityStatus <urn:usf:applicabilitystatus:pendingassessment> }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:inherentLikelihood ?il ; usf:inherentImpact ?ii ; usf:inherentScore ?is ;
                usf:residualLikelihood ?rl ; usf:residualImpact ?ri ; usf:residualScore ?rs .
          FILTER(?is != (?il * ?ii) || ?rs != (?rl * ?ri) || ?rs > ?is)
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:soaForEdition ?edition .
          { ?edition usf:hasFrameworkControl ?control .
            FILTER NOT EXISTS { $this usf:hasApplicabilityDecision/usf:decisionForControl ?control } }
          UNION
          { $this usf:hasApplicabilityDecision/usf:decisionForControl ?control .
            FILTER NOT EXISTS { ?edition usf:hasFrameworkControl ?control } }
          UNION
          { $this usf:hasApplicabilityDecision ?first, ?second .
            ?first usf:decisionForControl ?control . ?second usf:decisionForControl ?control .
            FILTER(STR(?first) < STR(?second)) }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          ?contract usf:declaresFacet $this .
          VALUES ?required { <urn:usf:nonclaim:nohumanacceptance> <urn:usf:nonclaim:nouiproductparity> <urn:usf:nonclaim:noaccessibilitycompliance> <urn:usf:nonclaim:nolaunchi18n> }
          FILTER NOT EXISTS { ?contract usf:disclaims ?required }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
        $this usf:semanticLifecycleState <urn:usf:semanticlifecyclestate:deprecated> .
        FILTER NOT EXISTS { $this usf:supersededBy ?successor . FILTER(?successor != $this) }
      }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
        $this usf:sourceBindingSource ?source ; usf:sourceBindingPath ?path ; usf:sourceBindingContentDigest ?digest .
        FILTER EXISTS { ?anyObservation a usf:SourceArtefactObservation }
        FILTER NOT EXISTS {
          ?source a usf:SourceArtefact ; usf:hasCurrentSourceObservation ?observation .
          ?observation usf:observedSourcePath ?path ; usf:observedContentDigest ?digest .
        }
      }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            $this usf:satisfies ?req .
            $this usf:hasFreshness ?f . ?f usf:canonicalName "stale" .
            ?req usf:requiresFreshness ?rf . ?rf usf:canonicalName "fresh" .
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
            $this usf:satisfies ?req .
            $this usf:usesProviderMode ?pm .
            ?req usf:requiresProviderMode ?need .
            FILTER NOT EXISTS { $this usf:usesProviderMode ?need }
            FILTER(?pm != ?need)
        }"^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:defaultLocale ?default .
              FILTER NOT EXISTS { $this usf:supportedLocale ?default }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:hasField ?left, ?right .
              FILTER(STR(?left) < STR(?right))
              { ?left usf:fieldName ?v . ?right usf:fieldName ?v }
              UNION
              { ?left usf:fieldOrder ?v . ?right usf:fieldOrder ?v }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:localisationKind <urn:usf:localisationrequirementkind:messagekey> .
              FILTER NOT EXISTS { $this usf:messageKey ?key }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:rendersViewModel ?model .
              FILTER NOT EXISTS { ?model usf:hasComponent ?component . ?component usf:componentKind <urn:usf:componentkind:action> }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:surfaceKind ?kind .
              FILTER(?kind IN (<urn:usf:surfacekind:webroute>, <urn:usf:surfacekind:queryview>))
              FILTER NOT EXISTS { $this usf:surfaceRoute ?route }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"
            SELECT $this WHERE {
              $this usf:surfaceKind <urn:usf:surfacekind:queryview> ; usf:rendersViewModel ?model .
              FILTER NOT EXISTS { ?model usf:loadsOperation ?operation ; usf:bindsInterface ?interface . ?interface usf:hasOperation ?operation }
            }
        "^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      { ?build usf:buildsArtefact $this } UNION { ?bundle usf:bundlesArtefact $this }
      FILTER NOT EXISTS { $this usf:canonicalChecksum ?checksum }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:plansArtefact ?artefact .
      ?artefact usf:generatedByComponent <urn:usf:generator:semanticcontract> .
      FILTER NOT EXISTS { $this usf:plansSemanticResource ?resource }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:plansArtefact ?artefact .
      { FILTER NOT EXISTS { ?artefact usf:generatedByComponent ?component . ?component a/rdfs:subClassOf* usf:CompilerComponent } }
      UNION
      { ?artefact usf:generatedByComponent ?left, ?right . FILTER(?left != ?right) }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          ?requirement usf:satisfiedByEvidence $this ; usf:requiresEvidenceStage ?stage .
          FILTER NOT EXISTS { $this usf:evidenceStage ?stage }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          ?requirement usf:satisfiedByEvidence $this .
          FILTER(
            NOT EXISTS { $this usf:evidenceSignature ?signature } ||
            NOT EXISTS { $this usf:evidenceChecksum ?checksum } ||
            NOT EXISTS {
              $this usf:integrityVerification ?verification .
              ?verification usf:verifiesEvidence $this ;
                usf:verificationState <urn:usf:resultstate:passed> .
            }
          )
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:hasFreshness <urn:usf:freshness:fresh> .
          FILTER NOT EXISTS { $this usf:evidenceFromProofResult ?proofResult }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:resultState <urn:usf:resultstate:detecteddefect> .
          FILTER NOT EXISTS { $this usf:detectedDefect ?defect }
        }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
          $this usf:realisationState ?state .
          FILTER(?state NOT IN (<urn:usf:realisationstate:contractonly>, <urn:usf:realisationstate:deferred>,
                                <urn:usf:realisationstate:notclaimed>, <urn:usf:realisationstate:deprecated>))
          FILTER NOT EXISTS { $this usf:realisingImplementation ?implementation }
          FILTER NOT EXISTS { $this usf:viaService ?service }
          FILTER NOT EXISTS { $this usf:viaAdapter ?adapter }
          FILTER NOT EXISTS { $this usf:viaBinding ?binding }
        }"^^http://www.w3.org/2001/XMLSchema#string

"
    PREFIX usf: <urn:usf:ontology:>
    SELECT ?this WHERE {
      ?this a usf:ResolvedWorkPackageDependency ;
        usf:resolvedDependencyStatus <urn:usf:workpackagedependencystatus:requiredprerequisite> .
    }
  "^^http://www.w3.org/2001/XMLSchema#string

"
    PREFIX usf: <urn:usf:ontology:>
    SELECT ?this WHERE {
      ?this a usf:WorkPackageDependencyObservation ;
        usf:workPackageDependencyStatus <urn:usf:workpackagedependencystatus:requiredprerequisite> .
    }
  "^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:dispositionOfSourceArtefact ?source ; usf:decidedAgainstObservation ?observation .
      FILTER NOT EXISTS { ?source usf:hasCurrentSourceObservation ?observation }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:hasDispositionOutputMode ?mode .
      { FILTER(?mode = <urn:usf:dispositionoutputmode:canonicaloutput>) FILTER NOT EXISTS { $this usf:assignedToArtefactPlan ?plan } }
      UNION
      { FILTER(?mode = <urn:usf:dispositionoutputmode:canonicaloutput>)
        $this usf:assignedToArtefactPlan ?left, ?right . FILTER(?left != ?right)
      }
      UNION
      { FILTER(?mode = <urn:usf:dispositionoutputmode:nooutput>) FILTER EXISTS { $this usf:assignedToArtefactPlan ?plan } }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:isDefaultDispositionPolicy ?default .
      BIND(EXISTS { $this usf:policyMatchesSourceIdentityDigest|usf:policyMatchesUniverse|usf:policyMatchesContentRole|usf:policyMatchesExactSemanticReference|usf:policyMatchesSourceBinding ?selector } AS ?hasSelector)
      FILTER((?default = false && !?hasSelector) || (?default = true && ?hasSelector))
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:isDefaultDispositionPolicy true ; usf:policyDispositionKind ?kind ; usf:policyDecisionState ?state ; usf:policyOutputMode ?mode .
      FILTER(?kind != <urn:usf:dispositionkind:reviewrequired> ||
             ?state != <urn:usf:dispositiondecisionstate:reviewrequired> ||
             ?mode != <urn:usf:dispositionoutputmode:nooutput>)
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:policyDispositionKind ?kind ; usf:policyOutputMode ?mode .
      FILTER NOT EXISTS { ?kind usf:permitsDispositionOutputMode ?mode }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:policyOutputMode ?mode .
      { FILTER(?mode = <urn:usf:dispositionoutputmode:canonicaloutput>)
        FILTER NOT EXISTS { $this usf:policyArtefactPlan ?plan }
        FILTER NOT EXISTS { $this usf:policyMatchesSourceBinding/usf:sourceBindingArtefactPlan ?plan }
      }
      UNION
      { FILTER(?mode = <urn:usf:dispositionoutputmode:canonicaloutput>)
        $this (usf:policyArtefactPlan|usf:policyMatchesSourceBinding/usf:sourceBindingArtefactPlan) ?left, ?right .
        FILTER(?left != ?right)
      }
      UNION
      { FILTER(?mode = <urn:usf:dispositionoutputmode:nooutput>)
        { FILTER EXISTS { $this usf:policyArtefactPlan ?plan } }
        UNION
        { FILTER EXISTS { $this usf:policyMatchesSourceBinding/usf:sourceBindingArtefactPlan ?plan } }
      }
    }"^^http://www.w3.org/2001/XMLSchema#string

"SELECT $this WHERE {
      $this usf:sourceIdentityDigest ?digest ; usf:canonicalName ?name .
      BIND(CONCAT("s", STR(?digest)) AS ?expected)
      FILTER(STR(?name) != ?expected || STR($this) != CONCAT("urn:usf:sourceartefact:", ?expected))
    }"^^http://www.w3.org/2001/XMLSchema#string
